using System;using System.Text;using UnityEngine;using TMPro;using LWS.TruckSports;using LWS.TruckBowling;
namespace LWS.TruckWifeCarrying {
public enum WifePhase {Countdown,Race,RaceResult,Complete}
public sealed class WifeMatch:SportsEventSession {
 public override bool SupportsRaceCountdown=>true;public override float RaceCountdownSeconds=>Phase==WifePhase.Countdown?Mathf.Max(0,3-age):-1;public override float RaceStartSeconds=>Phase==WifePhase.Race?Clock:-1;
 public WifePair[] pairs;public WifeCourse course;public SportsRallyViews views;public TextMesh[] identities;public TMP_InputField[] teamInputs;public TMP_Text[] roleLabels;public GameObject swapButton;public string[] teams={"Double Trouble","Roof Riders","Precious Cargo","Carry On"};public SportsRaceSeries series=new SportsRaceSeries();public WifePhase Phase{get;private set;}public float Clock{get;private set;}public bool Swapped{get;private set;}public int Seed{get;private set;}float age;int focus;readonly float[] times=new float[4],reaction=new float[4];readonly Vector2[] aiDrive=new Vector2[4];readonly int[] groups={0,1,2,3,0,1,2,3};readonly StringBuilder text=new StringBuilder(1400);
 [Serializable]sealed class Names {public string[] teams;}
 readonly float[] aiLastMoved=new float[4],aiReverseUntil=new float[4];readonly Vector3[] aiLastPosition=new Vector3[4];
 protected override void Awake(){base.Awake();try{var saved=JsonUtility.FromJson<Names>(LWS.TruckSports.SportsPrefs.GetString("WifeTeamNames.v1","{}"));if(saved?.teams?.Length==4)teams=saved.teams;}catch(Exception){}}
 protected override void Start(){base.Start();for(int i=0;i<4;i++){int slot=i;teamInputs[i].SetTextWithoutNotify(teams[i]);teamInputs[i].onEndEdit.AddListener(value=>{teams[slot]=string.IsNullOrWhiteSpace(value)?"Pair "+(slot+1):value.Trim();LWS.TruckSports.SportsPrefs.SetString("WifeTeamNames.v1",JsonUtility.ToJson(new Names{teams=teams}));LWS.TruckSports.SportsPrefs.Save();});}}
 public int DriverRole(int pair)=>pair+(Swapped?4:0);public int PassengerRole(int pair)=>pair+(Swapped?0:4);public override string Title=>"TRUCK WIFE CARRYING";public override int MinimumPlayers=>8;public override int MaximumPlayers=>8;public override int OptionCount=>2;public override string OptionLabel=>"BETWEEN-RACE ROLE SWAP: "+(option==0?"AVAILABLE":"AUTOMATIC");public override bool MultiViewHUD=>views!=null&&views.Humans>0;
 public override string SourcePolicy=>"Four pairs: left column drives, right column leans/braces. Up to four humans total.\nEach controller or shared stick has one owner; human partners share one camera.";
 public override string Help=>"PRECIOUS CARGO\nFour pairs race three rounds around the country circuit. Follow all five flags through bends, banks, bridge choices, mud and the flooded route or its safer outside bypass. The large truck carries a smaller partner on a visible roof cradle. Each driver and passenger has an independent name, source and AI difficulty; edit pair names through TEAM NAMES. Up to four humans can share pairs or join different pairs.\n\nDRIVER: movement accelerates, steers and brakes before reversing. Slow for banks, slalom, ramps and mud. PASSENGER: movement leans fore/aft and sideways; HOLD ACTION to brace. Lean changes the constrained physical load and transfers an equal opposite reaction to the driver. There is no extra propulsion. Excessive tilt or a violent impact can drop your partner.\n\nDROPPED PARTNER: stop within4.8m and under1.6m/s to pick up. The visible lift takes1.2s, then a fixed FIVE-SECOND stationary penalty. Other pairs keep racing. You cannot advance during pickup, skip gates or retrieve a partner from far away. Both trucks must cross carried. Ordered flags prevent bypass wins. A genuinely stranded pair or180s timeout is DNF, never an invented finish.\n\nValid finishers earn4/3/2/1 points; DNF zero. Three races, highest total; tied leaders race again. Between races choose SWAP ROLES, or select automatic swapping in setup. Role swaps retain each person’s name, device and pair score. Shared partners retain one view. Offline only; pause/disconnect preserves physics and scores.";
 public override string Header=>Title+" | "+(series.round>3?"TIEBREAK":"RACE "+series.round+" / 3")+" | "+course.weather.Description;
 public override string Status=>Phase==WifePhase.Countdown?Mathf.CeilToInt(3-age).ToString():Phase==WifePhase.Race?"DRIVE SMOOTHLY · PASSENGER LEAN / HOLD ACTION TO BRACE · "+Clock.ToString("F1")+"s":"PLACEMENTS LOCKED · ROLE SWAP AVAILABLE";
 public override int ScoreCardCount=>4;public override string ScoreCardLabel(int card)=>teams[card];public override int ScoreCardSource(int card)=>DriverRole(card);public override Color ScoreCardColor(int card)=>setup.players[card].color;public override string Standings{get{text.Clear();for(int i=0;i<4;i++)text.Append(teams[i]).Append("  ").Append(series.total[i]).Append(" PTS  ").Append(Phase==WifePhase.Countdown?"READY":Phase==WifePhase.Race?(pairs[i].State==WifeState.Inactive?"OUT OF TIEBREAK":pairs[i].State==WifeState.DNF?"DNF":pairs[i].State==WifeState.Finished?"FINISHED":pairs[i].State==WifeState.Dropped?"PARTNER DOWN":pairs[i].State==WifeState.Pickup?"LIFTING PARTNER":pairs[i].State==WifeState.Penalty?"RECOVERY "+Mathf.CeilToInt(pairs[i].PenaltyRemaining)+"s":"FLAGS "+pairs[i].Checkpoint+"/5"):series.ranks[i]>0?"#"+series.ranks[i]:pairs[i].State==WifeState.Inactive?"OUT OF TIEBREAK":"DNF").Append(i==3?"":"\n");return text.ToString();}}public override string Results=>(series.winner>=0?teams[series.winner]+" WINS\n\n":"TIED\n")+Standings;
 public override bool ValidateSources(out string reason){if(!base.ValidateSources(out reason))return false;int humans=0;for(int i=0;i<8;i++)if(setup.players[i].source!=BowlingSource.AI)humans++;if(humans>4){reason="At most four humans across all eight driver/passenger roles.";return false;}return true;}
 public override void RefreshExtraUI(){if(roleLabels==null)return;for(int i=0;i<8;i++)roleLabels[i].text="PAIR "+(i%4+1)+" · "+(i<4?"DRIVER":"PASSENGER");}
 protected override void BeginGame(){Seed=UnityEngine.Random.Range(1,100000);Swapped=false;series.Reset(4,false);BeginRace();}
 void BeginRace(){series.BeginRound();Phase=WifePhase.Countdown;age=Clock=0;course.weather.Configure(Seed+series.round,weather,0);for(int i=0;i<4;i++){reaction[i]=0;times[i]=float.PositiveInfinity;pairs[i].Prepare((series.eligible&(1<<i))!=0);aiLastMoved[i]=aiReverseUntil[i]=0;aiLastPosition[i]=pairs[i].driver.body.position;}views.Layout(groups);Gate();}
 Vector2 DriverAI(int i){if(Clock<reaction[i])return aiDrive[i];float level=(int)setup.players[DriverRole(i)].difficulty;reaction[i]=Clock+Mathf.Lerp(.26f,.07f,level*.5f);var pair=pairs[i];var t=pair.driver;var p=t.body.position;float speed=Vector3.Dot(t.body.linearVelocity,t.transform.forward);Vector3 aim;float desired;
 if(pair.State!=WifeState.Racing){aiLastMoved[i]=Clock;aiLastPosition[i]=p;}else if(Vector3.ProjectOnPlane(p-aiLastPosition[i],Vector3.up).sqrMagnitude>.55f*.55f){aiLastMoved[i]=Clock;aiLastPosition[i]=p;}
 if(pair.State==WifeState.Racing&&Clock-aiLastMoved[i]>1.7f&&Mathf.Abs(speed)<.8f&&t.Grounded){aiReverseUntil[i]=Clock+.75f;aiLastMoved[i]=Clock;}
 if(pair.State==WifeState.Racing&&Clock<aiReverseUntil[i]){course.Project(p,pair.Progress,out float side);return aiDrive[i]=new Vector2(side>0?.7f:-.7f,-.65f);}
 if(pair.State==WifeState.Dropped){aim=pair.passenger.body.position;desired=Vector3.Distance(aim,p)>4?5:0;}else{
  float s=pair.Progress,look=Mathf.Lerp(4,9,Mathf.Clamp01(Mathf.Abs(speed)/18)),target=Mathf.Min(WifeCourse.Finish+8,s+look),offset=(i-1.5f)*4;
  bool flooded=s>130&&s<185;bool bypass=flooded&&(level<1.5f||course.weather.Grip<.85f);if(bypass)offset=20;
  if(pair.State==WifeState.Racing&&!bypass){var ahead=Vector3.ProjectOnPlane(t.transform.forward,Vector3.up).normalized;if(Physics.SphereCast(p+Vector3.up*.6f,.5f,ahead,out var obstacle,Mathf.Clamp(Mathf.Abs(speed)*.7f,5,12),1,QueryTriggerInteraction.Ignore)&&obstacle.normal.y<.55f){course.Project(obstacle.point,s,out float obstructionSide);offset=Mathf.Clamp(obstructionSide+(offset<=obstructionSide?-3.2f:3.2f),-16,16);}else if(level>=1)for(int j=0;j<4;j++)if(j!=i&&pairs[j].State==WifeState.Racing&&pairs[j].Progress>s&&pairs[j].Progress-s<5&&Vector3.Distance(p,pairs[j].driver.body.position)<10){course.Project(pairs[j].driver.body.position,s,out float otherSide);if(Mathf.Abs(offset-otherSide)<2.7f)offset=Mathf.Clamp(otherSide+(offset<=otherSide?-3.5f:3.5f),-16,16);}}
  aim=course.loopCircuit?course.Point(target,offset):course.Surface(new Vector3(course.Center(target)+offset,0,target));desired=Mathf.Lerp(12,17,level*.5f);
  var a=course.loopCircuit?course.Point(s+2)-course.Point(s-2):new Vector3(course.Center(s+2)-course.Center(s-2),0,4);var b=course.loopCircuit?course.Point(s+look+2)-course.Point(s+look-2):new Vector3(course.Center(s+look+2)-course.Center(s+look-2),0,4);float arc=Vector3.ProjectOnPlane(aim-p,Vector3.up).magnitude;float curvature=Vector3.Angle(Vector3.ProjectOnPlane(a,Vector3.up),Vector3.ProjectOnPlane(b,Vector3.up))*Mathf.Deg2Rad/Mathf.Max(4,arc);float lateralAcceleration=Mathf.Lerp(2.8f,4,level*.5f)*Mathf.Clamp(course.Grip(p),.45f,1);desired=Mathf.Min(desired,Mathf.Sqrt(lateralAcceleration/Mathf.Max(.001f,curvature)));if(flooded&&!bypass)desired=Mathf.Min(desired,9);if(pair.Balance>17)desired=Mathf.Min(desired,6);
 }
 var delta=Vector3.ProjectOnPlane(aim-p,Vector3.up);var heading=Vector3.ProjectOnPlane(t.transform.forward,Vector3.up).normalized;float angle=Vector3.SignedAngle(heading,delta,Vector3.up);bool reverse=pair.State==WifeState.Dropped&&Mathf.Abs(angle)>95;float steer;
 if(reverse){steer=-Mathf.Clamp(Mathf.DeltaAngle(angle,180)/30,-1,1);}else{float wheelbase=Mathf.Abs(t.wheels[0].transform.localPosition.z-t.wheels[2].transform.localPosition.z)*t.transform.lossyScale.z;float lateral=Vector3.Dot(delta,Vector3.Cross(Vector3.up,heading));steer=Mathf.Atan2(2*wheelbase*lateral,Mathf.Max(4,delta.sqrMagnitude))*Mathf.Rad2Deg/Mathf.Max(1,t.steerAngle);if(Mathf.Abs(angle)>75){steer=Mathf.Sign(angle);desired=Mathf.Min(desired,4);}}
 float throttle=reverse?delta.magnitude>3?-.5f:0:Mathf.Clamp((desired-speed)*.6f,-1,1);if(pair.State==WifeState.Penalty||pair.State==WifeState.Pickup)throttle=speed>.2f?-1:0;aiDrive[i]=new Vector2(Mathf.Clamp(steer,-1,1),throttle);return aiDrive[i];}
 Vector2 PassengerAI(int i){var p=pairs[i];float level=(int)setup.players[PassengerRole(i)].difficulty;var local=p.driver.transform.InverseTransformDirection(p.driver.body.angularVelocity);float roll=Vector3.SignedAngle(Vector3.up,p.driver.transform.up,p.driver.transform.forward);float pitch=Vector3.SignedAngle(Vector3.up,p.driver.transform.up,p.driver.transform.right);return new Vector2(Mathf.Clamp(roll/24+local.z*.5f,-1,1),Mathf.Clamp(-pitch/30-local.x*.4f,-1,1))*Mathf.Lerp(.65f,1,level*.5f);}
 protected override void Simulate(float dt){age+=dt;if(Phase==WifePhase.Countdown){if(age>=3){Phase=WifePhase.Race;age=0;foreach(var p in pairs)p.Release();}return;}if(Phase==WifePhase.RaceResult){if(age>=7){if(series.winner>=0){Phase=WifePhase.Complete;EndMatch();}else{if(option==1)Swapped=!Swapped;BeginRace();}}return;}if(Phase!=WifePhase.Race)return;Clock+=dt;course.weather.Tick(Clock);int resolved=0;float front=float.NegativeInfinity;for(int i=0;i<4;i++){int d=DriverRole(i),p=PassengerRole(i);var drive=setup.players[d].source==BowlingSource.AI?DriverAI(i):commands[d];var lean=setup.players[p].source==BowlingSource.AI?PassengerAI(i):commands[p];bool brace=setup.players[p].source==BowlingSource.AI?(pairs[i].Balance>Mathf.Lerp(17,11,(int)setup.players[p].difficulty*.5f)||Mathf.Abs(aiDrive[i].x)>.06f&&pairs[i].driver.body.linearVelocity.magnitude>9):setup.players[p].released&&ActionHeld(p);pairs[i].Step(drive,lean,brace,dt);if(pairs[i].State==WifeState.Finished||pairs[i].State==WifeState.DNF||pairs[i].State==WifeState.Inactive)resolved++;else if(pairs[i].Progress>front){front=pairs[i].Progress;focus=i;}}if(Clock>=180){foreach(var p in pairs)if(p.State!=WifeState.Finished)p.Fail();resolved=4;}if(resolved==4){for(int i=0;i<4;i++){times[i]=pairs[i].FinishTime;pairs[i].Stop();}if(series.Resolve(times)){Phase=WifePhase.RaceResult;age=0;feedback.Play(5,0,true);Gate();Debug.Log("WIFE_RACE_LOCK race="+series.round+" ranks="+string.Join(",",series.ranks)+" points="+string.Join(",",series.total));}}}
 public void Dropped(WifePair pair,string reason){feedback.Play(2,0,true);Pulse(DriverRole(pair.slot),.25f,.15f);Debug.Log("WIFE_DROP pair="+pair.slot+" reason="+reason+" z="+pair.driver.body.position.z);}public void Pickup(WifePair pair){feedback.Play(3,0,true);}public void Arrived(WifePair pair){feedback.Play(5,0,true);}public void Impact(int slot,float speed){feedback.Play(1,speed);if(speed>5)Pulse(DriverRole(slot),.15f,.08f);}
 public override string ViewText(int view){int i=views.owners[view];var p=pairs[i];return "<color=#"+ColorUtility.ToHtmlStringRGB(setup.players[i].color)+">"+teams[i]+"</color> | "+series.total[i]+" PTS · RACE "+series.round+"\nDRIVE: "+setup.players[DriverRole(i)].name+" | LEAN: "+setup.players[PassengerRole(i)].name+"\n"+(p.State==WifeState.Dropped?"STOP NEAR YOUR PARTNER TO RETRIEVE":p.State==WifeState.Pickup?"LIFTING PARTNER":p.State==WifeState.Penalty?"RECOVERY +5s · "+p.PenaltyRemaining.ToString("F1"):p.State==WifeState.Finished?"FINISHED · "+p.FinishTime.ToString("F2")+"s":p.State==WifeState.DNF?"DNF · WATCHING LEADER":"FLAGS "+p.Checkpoint+"/5 · BALANCE "+p.Balance.ToString("F0")+"° · HOLD ACTION TO BRACE");}
 protected override void Present(float dt){if(pairs==null||views==null)return;views.Focus=focus;views.Follow(dt);if(swapButton!=null)swapButton.SetActive(Live&&Phase==WifePhase.RaceResult&&series.winner<0&&option==0);for(int i=0;i<4;i++){identities[i].gameObject.SetActive(pairs[i].State!=WifeState.Inactive);identities[i].transform.position=pairs[i].passenger.body.position+Vector3.up*1.2f;identities[i].text=teams[i];identities[i].color=setup.players[i].color;}for(int v=0;v<views.Humans;v++)if(pairs[views.owners[v]].State==WifeState.DNF||pairs[views.owners[v]].State==WifeState.Inactive)views.views[v].Pose(pairs[focus].driver.body.position,new Vector3(0,13,-24),72);else if(pairs[views.owners[v]].State==WifeState.Dropped){var p=pairs[views.owners[v]];var midpoint=(p.driver.body.position+p.passenger.body.position)*.5f;float distance=Vector3.Distance(p.driver.body.position,p.passenger.body.position);views.views[v].Pose(midpoint,new Vector3(0,10+Mathf.Min(distance*.3f,10),-18-Mathf.Min(distance*.5f,15)),72);}}
 public override void ExtraAction(string key){if(key=="teamsetup"&&!Running)menus.Show((SportsEventScreen)8);else if(key=="teamback")menus.Show(SportsEventScreen.Setup);else if(key=="swaproles"&&Live&&Phase==WifePhase.RaceResult&&series.winner<0&&option==0){Swapped=!Swapped;Gate();}}
 protected override void StopGame(){if(pairs!=null)foreach(var p in pairs)p.Stop();}protected override void StopSounds(){if(pairs!=null)foreach(var p in pairs){p.driver.StopSound();p.passenger.StopSound();}}protected override void SetPaused(bool paused)=>course?.weather?.Pause(paused);
}
